// ─── BUILDER ──────────────────────────────────────────────────────────────────

const QR_OPTION_KEYS = ["A", "B", "C", "D", "E"] as const;
const QR_INITIAL_ANSWER_KEYS = ["A", "B", "C", "D"] as const;

function normaliseQrOptionText(value: string) {
  return value.replace(/\s+/g, " ").trim().toLowerCase();
}

function formatQrFallbackNumber(value: number, decimals: number) {
  return value.toLocaleString("en-GB", {
    minimumFractionDigits: decimals,
    maximumFractionDigits: decimals,
  });
}

function makeQrFallbackOptionText(correctText: string, attempt: number) {
  const ratioMatch = correctText.match(/^(\d+):(\d+)$/);

  if (ratioMatch) {
    return `${Number(ratioMatch[1]) + attempt}:${ratioMatch[2]}`;
  }

  const fractionMatch = correctText.match(/^(\d+)\/(\d+)$/);

  if (fractionMatch) {
    return `${Number(fractionMatch[1]) + attempt}/${fractionMatch[2]}`;
  }

  const numericMatch = correctText.match(/^(.*?)(-?[\d,]+(?:\.\d+)?)(.*)$/);

  if (numericMatch) {
    const prefix = numericMatch[1];
    const rawNumber = numericMatch[2];
    const suffix = numericMatch[3];
    const value = Number(rawNumber.replace(/,/g, ""));
    const decimals = rawNumber.includes(".") ? rawNumber.split(".")[1].length : 0;
    const step =
      decimals > 0
        ? attempt / 10 ** decimals
        : Math.max(1, Math.round(Math.abs(value) * 0.04)) * attempt;
    const direction = attempt % 2 === 0 ? -1 : 1;
    const adjusted = Math.max(0, value + direction * step);

    return `${prefix}${formatQrFallbackNumber(adjusted, decimals)}${suffix}`;
  }

  return [
    "More information is required",
    "None of the listed options",
    "The result cannot be determined from the data",
    "The values are equal",
    "No change",
  ][attempt - 1] ?? `Alternative ${attempt}`;
}

function makeUniqueQrFallbackOptionText(
  correctText: string,
  distractors: string[],
  seed: number
) {
  const usedTexts = new Set(
    [correctText, ...distractors].map((text) => normaliseQrOptionText(text))
  );
  let attempt = (seed % 3) + 1;

  for (let tries = 0; tries < 12; tries += 1) {
    const text = makeQrFallbackOptionText(correctText, attempt);
    const normalisedText = normaliseQrOptionText(text);

    if (!usedTexts.has(normalisedText)) return text;

    attempt += 1;
  }

  return `Alternative ${seed + 1}`;
}

function buildQrOptions(
  correctText: string,
  distractors: [string, string, string],
  seed: number
) {
  const answerIndex = seed % QR_INITIAL_ANSWER_KEYS.length;
  const wrongs = distractors.slice(0, 3);
  wrongs.push(makeUniqueQrFallbackOptionText(correctText, wrongs, seed));
  const texts = [...wrongs];
  texts.splice(answerIndex, 0, correctText);
  return {
    options: texts.map((text, i) => ({
      key: QR_OPTION_KEYS[i],
      text,
    })),
    answer: QR_OPTION_KEYS[answerIndex],
  };
}

function buildQrQuestion(
  input: QrCuratedInput,
  inputIndex: number
): UCATQuestion[] {
  if (input.kind === "single") {
    const built = buildQrOptions(input.correct, input.distractors, inputIndex);
    return [
      {
        id: `user-curated-qr-${String(inputIndex + 1).padStart(4, "0")}-1`,
        section: "qr" as const,
        subtype: input.subtype,
        tags: input.tags ?? ["text-stem", "medium"],
        title: "Quantitative Reasoning Practice",
        leftTitle: input.leftTitle ?? "Data",
        stimulus: input.stimulus,
        visual: input.visual,
        question: input.question,
        ...built,
        explanation: input.explanation,
      },
    ];
  }
  const setId = `user-curated-qr-${String(inputIndex + 1).padStart(4, "0")}`;
  return input.questions.map((q, qIndex) => {
    const built = buildQrOptions(q.correct, q.distractors, inputIndex * 10 + qIndex);
    return {
      id: `${setId}-${qIndex + 1}`,
      section: "qr" as const,
      subtype: q.subtype,
      setId,
      tags: q.tags ?? ["data-display", "set-based", "medium"],
      title: "Quantitative Reasoning Practice",
      leftTitle: input.leftTitle ?? (input.visual ? "Data" : "Information"),
      stimulus: input.stimulus,
      visual: input.visual,
      question: q.question,
      ...built,
      explanation: q.explanation,
    };
  });
}

const CURATED_QR_QUESTIONS_FROM_CURATED: UCATQuestion[] =
  USER_CURATED_QR_INPUTS.flatMap(buildQrQuestion);

// ─── RAW CHART INPUTS ─────────────────────────────────────────────────────────
// Gemini provides: axis labels, data arrays, and questions.
// Builder calculates max and constructs the full chart visual.

type QrRawQuestion = {
  subtype:
    | "qr-graphs"
    | "qr-percentages"
    | "qr-rates-ratios"
    | "qr-averages"
    | "qr-units-geometry"
    | "qr-estimation";
  question: string;
  correct: string;
  distractors: [string, string, string];
  explanation: string;
};

type QrRawChartBase = {
  setId: string;
  title: string;
  yLabel: string;
  context: string;
  questions: QrRawQuestion[];
};

export type QrBarRawInput = QrRawChartBase & {
  chartType: "bar";
  data: Array<{ label: string; value: number }>;
};

export type QrLineRawInput = QrRawChartBase & {
  chartType: "line";
  data: Array<{ label: string; value: number }>;
};

export type QrGroupedBarRawInput = QrRawChartBase & {
  chartType: "grouped-bar";
  seriesLabels: string[];
  groups: Array<{ label: string; values: number[] }>;
};

export type QrChartRawInput = QrBarRawInput | QrLineRawInput | QrGroupedBarRawInput;

